const question = $('Webhook').first().json.body.question;

const expenses = [];
const income = [];

const summary = {
  balance: {},
  totals: {},
  monthlyTotals: {},
  yearlyTotals: {},
  categories: {},
  incomeSources: {},
  lastUpdated: ""
};

let section = "";

for (const item of $input.all()) {

  const row = item.json;

  // -------------------------
  // EXPENSES
  // -------------------------

  if ("Category" in row) {

    expenses.push({
      date: row["Date"],
      amount: Number(row["Amount ($)"]),
      category: row["Category"],
      description: row["Description"]
    });

    continue;
  }

  // -------------------------
  // INCOME
  // -------------------------

  if ("Source" in row) {

    income.push({
      date: row["Date"],
      amount: Number(row["Amount ($)"]),
      source: row["Source"],
      description: row["Description"]
    });

    continue;
  }

  // -------------------------
  // SUMMARY
  // -------------------------

  if ("Metric" in row) {

    const metric = String(row["Metric"]).trim();
    const value = String(row["Value"]).trim();

    // Detect sections
    if (metric.includes("💵 BALANCE")) {
      section = "balance";
      continue;
    }

    if (metric.includes("📅 DAILY")) {
      section = "daily";
      continue;
    }

    if (metric.includes("📆 MONTHLY")) {
      section = "monthly";
      continue;
    }

    if (metric.includes("📅 YEARLY")) {
      section = "yearly";
      continue;
    }

    if (metric.includes("📁 EXPENSES")) {
      section = "categories";
      continue;
    }

    if (metric.includes("💰 INCOME")) {
      section = "income";
      continue;
    }

    // Balance section
    if (section === "balance") {

      if (metric === "Initial Balance")
        summary.balance.initial = value;

      else if (metric === "Current Balance")
        summary.balance.current = value;

      else if (metric === "Total Income")
        summary.totals.totalIncome = value;

      else if (metric === "Total Expenses")
        summary.totals.totalExpenses = value;

      else if (metric === "Total Expense Entries")
        summary.totals.expenseEntries = value;

      else if (metric === "Total Income Entries")
        summary.totals.incomeEntries = value;

    }

    // Monthly totals
    else if (section === "monthly") {

      summary.monthlyTotals[metric] = value;

    }

    // Yearly totals
    else if (section === "yearly") {

      summary.yearlyTotals[metric] = value;

    }

    // Categories
    else if (section === "categories") {

      summary.categories[metric] = value;

    }

    // Income sources
    else if (section === "income") {

      summary.incomeSources[metric] = value;

    }

    // Last Updated
    if (metric === "Last Updated") {

      summary.lastUpdated = value;

    }

  }

}

return [{
  json: {
    question,
    expenses,
    income,
    summary
  }
}];
